{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_pod_name, count(*) n, min(value) mn, max(value) mx FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'profile%' AND metric IN ('k8s.container.restarts','k8s.container.ready') GROUP BY ALL ORDER BY 2,1",
          "claim": "Profile pod profile-798c5d9c47-klz99 restarts up to 6 times and reports ready=0 during the incident; normal period shows 0 restarts."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, count(*) n FROM abnormal_traces WHERE service_name='profile' UNION ALL SELECT 'norm', count(*) FROM normal_traces WHERE service_name='profile'",
          "claim": "The profile service emits no spans at all in the abnormal window, while the normal window has over 2,000."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, count(*) n, round(quantile_cont(duration,0.5)/1e6,3) p50ms, round(quantile_cont(duration,0.95)/1e6,3) p95ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles' UNION ALL SELECT 'norm', count(*), round(quantile_cont(duration,0.5)/1e6,3), round(quantile_cont(duration,0.95)/1e6,3) FROM normal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles'",
          "claim": "Frontend's GetProfiles calls to profile fail near-instantly in the abnormal window (p50 0.013 ms) versus about 7.5 ms p95 normally."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE level='ERROR' GROUP BY ALL",
          "claim": "Frontend logs 1627 ERROR lines with the message 'Get profiles failed' during the abnormal window; no other service logs errors."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(avg(CASE WHEN attr_status_code='STATUS_CODE_ERROR' THEN 1 ELSE 0 END),3) err, round(quantile_cont(duration,0.95)/1e6,2) p95ms FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' GROUP BY ALL ORDER BY 1",
          "claim": "User-facing frontend HTTP /hotels traffic continues but its GetProfiles dependency fails fast, so frontend logs ERROR 'Get profiles failed' on each request."
        }
      ]
    }
  ]
}
